1	namespace Engine.Services.Factories;
2	
3	using System;
4	using System.Linq;
5	using System.IO;
6	using System.Xml;
7	using Engine.Models;
8	using Engine.Models.Actions;
9	using Engine.Models.Shared;
10	
11	public static class ItemFactory
12	{
13	    // Resolved against the folder holding the .exe, not the current working directory,
14	    // so the game and the tests find the data file wherever they are launched from.
15	    private static readonly string GAME_DATA_FILENAME =
16	        Path.Combine(AppContext.BaseDirectory, "GameData", "GameItems.xml");
17	
18	    private static readonly List<GameItem> _standardGameItems = new List<GameItem>();
19	
20	    static ItemFactory()
21	    {
22	        if (!File.Exists(GAME_DATA_FILENAME))
23	        {
24	            throw new FileNotFoundException($"Missing data file: {GAME_DATA_FILENAME}");
25	        }
26	
27	        XmlDocument data = new XmlDocument();
28	        data.LoadXml(File.ReadAllText(GAME_DATA_FILENAME));
29	
30	        // XPath is case sensitive - these must match the element names in GameItems.xml exactly.
31	        LoadItemsFromNodes(data.SelectNodes("/GameItems/Weapons/Weapon"));
32	        LoadItemsFromNodes(data.SelectNodes("/GameItems/HealingItems/HealingItem"));
33	        LoadItemsFromNodes(data.SelectNodes("/GameItems/MiscellaneousItems/MiscellaneousItem"));
34	    }
35	
36	    public static GameItem CreateGameItem(int itemTypeId)
37	    {
38	        GameItem? standardItem = _standardGameItems.FirstOrDefault(item => item.ItemTypeId == itemTypeId);
39	        if(standardItem == null)
40	        {
41	            throw new ArgumentException($"ItemTypeId '{itemTypeId}' does not exist", nameof(itemTypeId));
42	        }
43	        return standardItem.Clone();
44	    }
45	    private static void LoadItemsFromNodes(XmlNodeList? nodes)
46	    {
47	        if(nodes == null)
48	        {
49	            return;
50	        }
51	        foreach(XmlNode node in nodes)
52	        {
53	            GameItem.ItemCategory itemCategory = DetermineItemCategory(node.Name);
54	            GameItem gameItem = new GameItem(
55	                itemCategory,
56	                node.AttributeAsInt("ID"),
57	                node.AttributeAsString("Name"),
58	                node.AttributeAsInt("Price"),
59	                itemCategory == GameItem.ItemCategory.Weapon
60	            );
61	
62	            switch (itemCategory)
63	            {
64	                case GameItem.ItemCategory.Weapon:
65	                    gameItem.Action = new AttackWithWeapon(gameItem,
66	                        node.AttributeAsString("DamageDice"));
67	                    break;
68	                case GameItem.ItemCategory.Consumable:
69	                    gameItem.Action = new Heal(gameItem,
70	                        node.AttributeAsInt("HitPointsToHeal"));
71	                    break;
72	            }
73	
74	            _standardGameItems.Add(gameItem);
75	        }
76	    }
77	    private static GameItem.ItemCategory DetermineItemCategory(string itemType)
78	    {
79	        switch (itemType)
