namespace Engine.Services.Factories;
using Engine.Models;
using System;
using System.IO;
using System.Xml;
using Engine.Models.Shared;

public static class WorldFactory
{
    // Resolved against the folder holding the .exe, not the current working directory,
    // so the game and the tests find the data file wherever they are launched from.
    private static readonly string GAME_DATA_FILENAME =
        Path.Combine(AppContext.BaseDirectory, "GameData", "Locations.xml");

    public static World CreateWorld()
    {
        if (!File.Exists(GAME_DATA_FILENAME))
        {
            throw new FileNotFoundException($"Missing data file: {GAME_DATA_FILENAME}");
        }

        World world = new World();

        XmlDocument data = new XmlDocument();
        data.LoadXml(File.ReadAllText(GAME_DATA_FILENAME));
        string rootImagePath =
            data.SelectSingleNode("/Locations").AttributeAsString("RootImagePath");
        LoadLocationsFromNodes(world, rootImagePath, data.SelectNodes("/Locations/Location"));

        return world;
    }
    private static void LoadLocationsFromNodes(World world, string rootImagePath, XmlNodeList nodes)
    {   
        if(nodes == null)
        {
            return;
        }
        foreach(XmlNode node in nodes)
        {
            Location location = new Location(
            node.AttributeAsString("Name"),
            node.SelectSingleNode("./Description")?.InnerText ?? "",
            node.AttributeAsInt("X"),
            node.AttributeAsInt("Y"),
            $".{rootImagePath}{node.AttributeAsString("ImageName")}"
            );

            AddMonsters(location, node.SelectNodes("./Monsters/Monster"));
            AddQuests(location, node.SelectNodes("./Quests/Quest"));
            AddTraders(location, node.SelectSingleNode("./Trader"));

            world.AddLocation(location);
        }
    }
    private static void AddMonsters(Location location, XmlNodeList monsters)
    {
        if(monsters == null)
        {
            return;
        }
        foreach(XmlNode monsterNode in monsters)
        {
            location.AddMonster(monsterNode.AttributeAsInt("ID"), monsterNode.AttributeAsInt("Percent"));
        }
    }
    private static void AddQuests(Location location, XmlNodeList quests)
    {
        if(quests == null)
        {
            return;
        }
        foreach(XmlNode questNode in quests)
        {
            location.QuestsAvailableHere.Add(QuestFactory.GetQuestById(questNode.AttributeAsInt("ID")));
        }
    }
    private static void AddTraders(Location location, XmlNode trader)
    {
        if(trader == null)
        {
            return;
        }
        location.TraderHere = TraderFactory.GetTraderByID(trader.AttributeAsInt("ID"));
    }
}

