13	public class GameSession : INotifyPropertyChanged
14	{
15	    private readonly MessageBroker _messageBroker = MessageBroker.GetInstance();
16	    private Battle _currentBattle;
17	    private Location _currentLocation = null!;
18	    private Monster? _currentMonster;
19	    private Player _currentPlayer = null!;
20	
21	    public event PropertyChangedEventHandler? PropertyChanged;
22	
23	    public string Version = "0.1.000";
24	
25	    [JsonIgnore]
26	    public GameDetails GameDetails {get; private set;}
27	
28	    [JsonIgnore]
29	    public World CurrentWorld { get; }
30	    public Player CurrentPlayer {
31	        get{return _currentPlayer;}
32	        set{
33	            if(_currentPlayer != null)
34	            {
35	                _currentPlayer.OnLeveledUp -= OnCurrentPlayerLeveledUp;
36	                _currentPlayer.OnKilled -= OnPlayerKilled;
37	            }
38	            _currentPlayer = value;
39	            if(_currentPlayer != null)
40	            {
41	                _currentPlayer.OnLeveledUp += OnCurrentPlayerLeveledUp;
42	                _currentPlayer.OnKilled += OnPlayerKilled;
43	            }
44	        }
45	    }
46	    // Quests and monsters must refresh even when moving back to the same location
47	    // (e.g. respawning at home), so Fody must not skip the setter for equal values.
48	    [DoNotCheckEquality]
49	    public Location CurrentLocation {
50	    get{return _currentLocation;}
51	    set{
52	        _currentLocation = value;
53	
54	        CompleteQuestsAtLocation();
55	        GivePlayerQuestsAtLocation();
56	        CurrentMonster = MonsterFactory.GetMonsterFromLocation(CurrentLocation);
57	
58	        CurrentTrader = CurrentLocation.TraderHere;
59	        }
60	    }
61	    [JsonIgnore]
62	    public Monster? CurrentMonster
63	    {
64	        get{return _currentMonster;}
65	        set{
66	            if(_currentMonster != null)
67	            {
68	                _currentBattle.OnCombatVictory -= OnCurrentMonsterKilled;
69	                _currentBattle.Dispose();
70	                _currentBattle = null;
71	            }
72	            _currentMonster = value;
73	
74	            if(_currentMonster != null)
75	            {
76	                _currentBattle = new Battle(CurrentPlayer, CurrentMonster);
77	                _currentBattle.OnCombatVictory += OnCurrentMonsterKilled;
78	            }
79	        }
80	    }
81	    [JsonIgnore]
82	    public Trader? CurrentTrader {get; private set;}
83	    [JsonIgnore]
84	    public bool HasLocationToNorth => CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate + 1) != null;
85	    [JsonIgnore]
86	    public bool HasLocationToWest => CurrentWorld.LocationAt(CurrentLocation.XCoordinate - 1, CurrentLocation.YCoordinate) != null;
87	    [JsonIgnore]
88	    public bool HasLocationToEast => CurrentWorld.LocationAt(CurrentLocation.XCoordinate + 1, CurrentLocation.YCoordinate) != null;
89	    [JsonIgnore]
90	    public bool HasLocationToSouth =>  CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate - 1) != null;
91	    [JsonIgnore]
92	    public bool HasMonster => CurrentMonster != null;
93	    [JsonIgnore]
94	    public bool HasTrader => CurrentTrader != null;
95	
96	    public GameSession(Player player, int xCoordinate, int yCoordinate)
97	    {   
98	        PopulateGameDetails();
99	
100	        CurrentWorld = WorldFactory.CreateWorld();
101	        CurrentPlayer = player;
102	        CurrentLocation = CurrentWorld.LocationAt(xCoordinate, yCoordinate);
103	    }
104	
105	    private Location HomeLocation()
106	    {
107	        return CurrentWorld.LocationAt(0, -1)
108	            ?? throw new InvalidOperationException("The world has no location at (0, -1) to use as Home.");
109	    }
