131	    private void MoveTo(int xCoordinate, int yCoordinate)
132	    {
133	        Location? destination = CurrentWorld.LocationAt(xCoordinate, yCoordinate);
134	        if (destination != null)
135	        {
136	            CurrentLocation = destination;
137	        }
138	    }
