140	    private void PopulateGameDetails()
141	    {
142	        GameDetails = GameDetailService.ReadGameDetails();
143	    }
144	
145	    private void GivePlayerQuestsAtLocation()
146	    {
147	        foreach (Quest quest in CurrentLocation.QuestsAvailableHere)
148	        {
149	            if (!CurrentPlayer.Quests.Any(q => q.Quest.Id == quest.Id))
150	            {
151	                CurrentPlayer.Quests.Add(new QuestStatus(quest));
152	                _messageBroker.RaiseMessage("");
153	                _messageBroker.RaiseMessage($"You received the {quest.Name} quest");
154	                _messageBroker.RaiseMessage(quest.Description);
155	                _messageBroker.RaiseMessage("return with:");
156	                foreach(ItemQuantity item in quest.CompleteItems)
157	                {
158	                    _messageBroker.RaiseMessage($"   {item.Quantity} {ItemFactory.CreateGameItem(item.ItemID).Name}");
159	                }
160	                _messageBroker.RaiseMessage("And you will receive");
161	                _messageBroker.RaiseMessage($"   {quest.RewardExperiencePoints} experience points");
162	                _messageBroker.RaiseMessage($"   {quest.RewardGold} gold");
163	                foreach(ItemQuantity itemQuantity in quest.RewardItems)
164	                {
165	                    _messageBroker.RaiseMessage($"   {itemQuantity.Quantity} {ItemFactory.CreateGameItem(itemQuantity.ItemID).Name}");
166	                }
167	            }
168	        }
169	    }
170	
171	    private void CompleteQuestsAtLocation()
172	    {
173	        foreach(Quest quest in CurrentLocation.QuestsAvailableHere)
174	        {
175	            QuestStatus? questToComplete =
176	                CurrentPlayer.Quests.FirstOrDefault(q => q.Quest.Id == quest.Id &&
177	                                                            !q.IsCompleted);
178	
179	            if(questToComplete != null)
180	            {
181	                if(CurrentPlayer.Inventory.HasAllTheseItems(quest.CompleteItems))
182	                {
183	                    CurrentPlayer.RemoveItemsFromInventory(quest.CompleteItems); 
184	                    _messageBroker.RaiseMessage("");
185	                    _messageBroker.RaiseMessage($"You completed the '{quest.Name}' quest");
186	
187	                    // Give the player the quest rewards
188	                    _messageBroker.RaiseMessage($"You receive {quest.RewardExperiencePoints} experience points");
189	                    CurrentPlayer.AddExperience(quest.RewardExperiencePoints);
190	
191	                    _messageBroker.RaiseMessage($"You receive {quest.RewardGold} gold");        
192	                    CurrentPlayer.ReceiveGold(quest.RewardGold);
193	            
194	
195	                    foreach(ItemQuantity itemQuantity in quest.RewardItems)
196	                    {
197	                        GameItem rewardItem = ItemFactory.CreateGameItem(itemQuantity.ItemID);
198	                        
199	                        _messageBroker.RaiseMessage($"You receive a {rewardItem.Name}");
200	                        CurrentPlayer.AddItemToInventory(rewardItem);
201	                    }
202	
203	                    // Mark the Quest as completed
204	                    questToComplete.IsCompleted = true;
205	                }
206	            }
207	        }
208	    }
209	    private void GetMonsterAtLocation()
210	    {
211	        CurrentMonster = MonsterFactory.GetMonsterFromLocation(CurrentLocation);
212	    }
213	
214	    public void AttackCurrentMonster()
215	    {
216	        _currentBattle?.AttackOpponent();
217	    }
218	
219	    public void UseCurrentConsumable()
220	    {
221	        if(CurrentPlayer.CurrentConsumable != null)
222	        {
223	            if (_currentBattle == null)
224	            {
225	                CurrentPlayer.OnActionPerformed += OnConsumableActionPerformed;
226	            }
227	
228	            CurrentPlayer.UseCurrentConsumable();
229	
230	            if (_currentBattle == null)
231	            {
232	                CurrentPlayer.OnActionPerformed -= OnConsumableActionPerformed;
233	            }
234	        }
235	    }
236	
237	    private void OnConsumableActionPerformed(object sender, string result)
238	    {
239	        _messageBroker.RaiseMessage(result);
240	    }
241	
242	    public void CraftItemUsing(Recipe recipe)
243	    {
244	        if (CurrentPlayer.Inventory.HasAllTheseItems(recipe.Ingredients))
245	        {
246	            CurrentPlayer.RemoveItemsFromInventory(recipe.Ingredients);
247	            foreach(ItemQuantity itemQuantity in recipe.OutputItems)
248	            {
249	                for(int i = 0; i < itemQuantity.Quantity; i++)
250	                {   
251	                    GameItem outputItem = ItemFactory.CreateGameItem(itemQuantity.ItemID);
252	                    CurrentPlayer.AddItemToInventory(outputItem);
253	                    _messageBroker.RaiseMessage($"You crafted 1 {outputItem.Name}");
254	                }
255	            }
256	        }
257	        else
258	        {
259	            _messageBroker.RaiseMessage("You dont have the requiered ingredients:");
260	            foreach(ItemQuantity itemQuantity in recipe.Ingredients)
261	            {
262	                _messageBroker.RaiseMessage(itemQuantity.QuantityItemDescription);
263	            }
264	        }
265	    }
266	
267	    private void OnPlayerKilled(object? sender, System.EventArgs eventArgs)
268	    {
269	        _messageBroker.RaiseMessage("");
270	        _messageBroker.RaiseMessage("You have been killed");
271	
272	        CurrentLocation = HomeLocation();
273	        CurrentPlayer.CompleteHeal();
