using System.Windows;
using Engine.Models;
using Engine.ViewModels;

namespace Engine.Windows;

public partial class TradeWindow : Window
{
    public GameSession? Session => DataContext as GameSession;
    public TradeWindow()
    {
        InitializeComponent();
    }

    private void OnClick_Sell(object sender, RoutedEventArgs e)
    {
        GameItem? item = ItemFrom(sender);
        Trader? trader = Session?.CurrentTrader;
        Player? player = Session?.CurrentPlayer;

        if(item == null || trader == null || player == null)
        {
            return;
        }

        if(trader.Gold < item.Price)
        {
            MessageBox.Show($"{trader.Name} cannot afford that");
            return;
        }

        trader.SpendGold(item.Price);
        player.ReceiveGold(item.Price);
        trader.AddItemToInventory(item);
        player.RemoveItemFromInventory(item);
    }

    private void OnClick_Buy(object sender, RoutedEventArgs e)
    {
        GameItem? item = ItemFrom(sender);
        Trader? trader = Session?.CurrentTrader;
        Player? player = Session?.CurrentPlayer;

        if(item == null || trader == null || player == null)
        {
            return;
        }

        if(player.Gold < item.Price)
        {
            MessageBox.Show("You dont have enaugh Gold");
            return;
        }

        player.SpendGold(item.Price);
        trader.ReceiveGold(item.Price);
        player.AddItemToInventory(item);
        trader.RemoveItemFromInventory(item);
    }

    private static GameItem? ItemFrom(object sender)
    {
        return (((FrameworkElement)sender).DataContext as GroupedInventoryItem)?.Item;
    }

    private void OnClick_Close(object sender, RoutedEventArgs e)
    {
        Close();
    }
}

