1	using Microsoft.VisualStudio.TestTools.UnitTesting;
2	using Engine.Services.Factories;
3	using Engine.Models;
4	
5	namespace TestEngine.Models
6	{
7	    [TestClass]
8	    public class TestCombat
9	    {
10	        // Dexterity 30 against the snake's 15 puts the hit chance above 100%, so attacks
11	        // never miss and the damage tests don't depend on the random roll.
12	        private static Player NewPlayer(int maximumHitPoints = 10) =>
13	            TestPlayerBuilder.NewPlayer(maximumHitPoints: maximumHitPoints, dexterity: 30);
14	
15	        [TestMethod]
16	        public void AttackingAMonsterReducesItsHitPoints()
17	        {
18	            Player player = NewPlayer();
19	            player.AddItemToInventory(ItemFactory.CreateGameItem(1001)); // Pointy Stick, 1-2 damage
20	            player.CurrentWeapon = player.Inventory.Weapons[0];
21	
22	            Monster snake = MonsterFactory.GetMonster(1);
23	            int startingHitPoints = snake.CurrentHitPoints;
24	
25	            player.UseCurrentWeaponOn(snake);
26	
27	            Assert.IsTrue(snake.CurrentHitPoints < startingHitPoints,
28	                $"expected damage, but hit points went from {startingHitPoints} to {snake.CurrentHitPoints}");
29	        }
30	
31	        [TestMethod]
32	        public void EnoughAttacksKillsAMonster()
33	        {
34	            Player player = NewPlayer();
35	            player.AddItemToInventory(ItemFactory.CreateGameItem(1001));
36	            player.CurrentWeapon = player.Inventory.Weapons[0];
37	
38	            Monster snake = MonsterFactory.GetMonster(1);
39	            bool killedEventRaised = false;
40	            snake.OnKilled += (sender, args) => killedEventRaised = true;
41	
42	            // Pointy Stick does at least 1 damage per hit and the snake has 4 hit points,
43	            // so 20 swings is far more than enough even with misses.
44	            for (int i = 0; i < 20 && !snake.IsDead; i++)
45	            {
46	                player.UseCurrentWeaponOn(snake);
47	            }
48	
49	            Assert.IsTrue(snake.IsDead, "snake survived 20 attacks");
50	            Assert.AreEqual(0, snake.CurrentHitPoints, "a dead entity should sit at exactly 0 hit points");
51	            Assert.IsTrue(killedEventRaised, "OnKilled was never raised");
52	        }
53	
54	        [TestMethod]
55	        public void AConsumableHealsItsUser()
56	        {
57	            Player player = NewPlayer();
58	            player.TakeDamage(5);
59	            player.AddItemToInventory(ItemFactory.CreateGameItem(2001)); // Granola bar, heals 2
60	            player.CurrentConsumable = player.Inventory.Consumables[0];
61	
62	            player.UseCurrentConsumable();
63	
64	            Assert.AreEqual(7, player.CurrentHitPoints);
65	            Assert.IsFalse(player.Inventory.HasConsumable, "the consumable should be gone after use");
66	            Assert.IsNull(player.CurrentConsumable, "a consumed item should no longer be selected");
67	        }
68	
69	        [TestMethod]
70	        public void TwoHoldersOfTheSameItemTypeDoNotShareActionMessages()
71	        {
72	            Monster first = MonsterFactory.GetMonster(1);
73	            Monster second = MonsterFactory.GetMonster(1);
