using System.IO;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using Engine.Models;
using Engine.ViewModels;
using Engine.Windows;

// Renders the real MainWindow off-screen to PNG files so layout/binding changes can be checked.
// args[0] = output folder, args[1] = file name prefix
class Program
{
    [STAThread]
    static void Main(string[] args)
    {
        string outDir = args[0];
        string prefix = args[1];

        // 1) Fresh character at the Town Square: carries a Granola bar, no monster here.
        var vm = new CharacterCreationViewModel { Name = "Jakob" };
        Player withConsumable = vm.GetPlayer();
        Render(new MainWindow(withConsumable, 0, 0), Path.Combine(outDir, prefix + "_town_square.png"));

        // 2) Same kit minus the Granola bar, in the Herbalist's Garden (snakes): weapon row
        //    should show, consumable row should not.
        Player withoutConsumable = vm.GetPlayer();
        withoutConsumable.RemoveItemFromInventory(withoutConsumable.Inventory.Consumables[0]);
        Render(new MainWindow(withoutConsumable, 0, 2), Path.Combine(outDir, prefix + "_garden_no_consumable.png"));

        // Exit without closing the windows, so the "save your game?" prompt never opens.
        Environment.Exit(0);
    }

    static void Render(Window window, string file)
    {
        window.Width = 1024;
        window.Height = 768;
        window.WindowStartupLocation = WindowStartupLocation.Manual;
        window.Left = -4000;
        window.Top = -4000;
        window.ShowActivated = false;
        window.ShowInTaskbar = false;
        window.Show();
        DoEvents();

        var content = (FrameworkElement)window.Content;
        var bitmap = new RenderTargetBitmap((int)content.ActualWidth, (int)content.ActualHeight, 96, 96, PixelFormats.Pbgra32);
        bitmap.Render(content);
        var encoder = new PngBitmapEncoder();
        encoder.Frames.Add(BitmapFrame.Create(bitmap));
        using FileStream stream = File.Create(file);
        encoder.Save(stream);
        Console.WriteLine("wrote " + file);
    }

    static void DoEvents()
    {
        var frame = new DispatcherFrame();
        Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,
            new Action(() => frame.Continue = false));
        Dispatcher.PushFrame(frame);
    }
}

